#!/bin/bash
# Uninstall script for Tumult Hype
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Tumult Hype..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Tumult Hype if running..."
pkill -f "Tumult Hype" 2>/dev/null || true

# Remove /Applications/Hype4.app
echo "Removing /Applications/Hype4.app..."
if [ -d "/Applications/Hype4.app" ]; then
    rm -rf "/Applications/Hype4.app" 2>/dev/null || true
elif [ -f "/Applications/Hype4.app" ]; then
    rm -f "/Applications/Hype4.app" 2>/dev/null || true
fi

# Remove /Applications/{'target': 'Hype 4.app'}
echo "Removing /Applications/{'target': 'Hype 4.app'}..."
if [ -d "/Applications/{'target': 'Hype 4.app'}" ]; then
    rm -rf "/Applications/{'target': 'Hype 4.app'}" 2>/dev/null || true
elif [ -f "/Applications/{'target': 'Hype 4.app'}" ]; then
    rm -f "/Applications/{'target': 'Hype 4.app'}" 2>/dev/null || true
fi

# Remove $HOME/Library/Containers/com.tumult.Hype4
echo "Removing $HOME/Library/Containers/com.tumult.Hype4..."
if [ -d "$HOME/Library/Containers/com.tumult.Hype4" ]; then
    rm -rf "$HOME/Library/Containers/com.tumult.Hype4" 2>/dev/null || true
elif [ -f "$HOME/Library/Containers/com.tumult.Hype4" ]; then
    rm -f "$HOME/Library/Containers/com.tumult.Hype4" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.tumult.Hype4.plist
echo "Removing $HOME/Library/Preferences/com.tumult.Hype4.plist..."
